INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしだって\nやるときはやるよ！", 24001, 24, "2030/12/17 14:59:59", 1, 10040, 0, "リン", 0, 102601, 0, 0, "2020/04/30 12:00:00", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("ふぅ…\nこれであたしの仕事は\n終わりだね", 24002, 24, "2030/12/17 14:59:59", 1, 10040, 0, "リン", 0, 102601, 1, 0, "2020/04/30 12:00:00", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("終わった終わった\n一人でもなんとか\nなるもんだね", 24003, 24, "2030/12/17 14:59:59", 1, 10040, 0, "リン", 0, 102601, 2, 0, "2020/04/30 12:00:00", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やったね！\nこれでようやく\nサボれるよ…", 24004, 24, "2030/12/17 14:59:59", 2, 10040, 0, "リン", 0, 102601, 3, 0, "2020/04/30 12:00:00", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 24005, 24, "2030/12/17 14:59:59", 1, 10040, 0, "リン", 0, 102601, 4, 0, "2020/04/30 12:00:00", 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしを敵に回した\n恐ろしさ\n思い知ったか！", 24006, 24, "2030/12/17 14:59:59", 2, 10040, 0, "リン", 0, 102601, 5, 0, "2020/04/30 12:00:00", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしも意外と\nやるもんでしょ？", 24007, 24, "2030/12/17 14:59:59", 2, 10040, 0, "リン", 0, 102601, 6, 0, "2020/04/30 12:00:00", 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nねずみの逃げ足\n速すぎるよ…", 24008, 24, "2030/12/17 14:59:59", 4, 10040, 0, "リン", 0, 102601, 7, 0, "2020/04/30 12:00:00", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("このままじゃ\nまっひ～に\n叱られちゃうよ", 24009, 24, "2030/12/17 14:59:59", 4, 10040, 0, "リン", 0, 102601, 8, 0, "2020/04/30 12:00:00", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("まじめに\nやったんだけどな…\n悔しいな～", 24010, 24, "2030/12/17 14:59:59", 4, 10040, 0, "リン", 0, 102601, 9, 0, "2020/04/30 12:00:00", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やられた…\nねずみって意外と\nてごわいね", 24011, 24, "2030/12/17 14:59:59", 4, 10040, 0, "リン", 0, 102601, 10, 0, "2020/04/30 12:00:00", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("おのれ～\nあたしのチーズを\n盗みやがって～！", 24012, 24, "2030/12/17 14:59:59", 4, 10040, 0, "リン", 0, 102601, 11, 0, "2020/04/30 12:00:00", 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nけど、次こそは\n守り抜くよ…", 24013, 24, "2030/12/17 14:59:59", 1, 10040, 0, "リン", 0, 102601, 12, 1.81, "2020/04/30 12:00:00", 4);
